import type { UIMessage } from 'ai';
import type { ComponentType, ReactNode } from 'react';

export type AgentMessagePart = UIMessage['parts'][number];

export type AgentMessageMessages = {
	assistantRole: string;
	audioAttachment: string;
	documentSource: string;
	fileAttachment: string;
	imageAttachment: string;
	malformedPart: string;
	openSource: string;
	reasoning: string;
	reasoningStreaming: string;
	step: (step: number) => string;
	systemRole: string;
	toolApprovalReason: string;
	toolInput: string;
	toolOutput: string;
	toolState: (state: string, approved?: boolean) => string;
	unknownPart: (type: string) => string;
	unnamedAttachment: string;
	unnamedSource: string;
	unnamedTool: string;
	userRole: string;
};

export const defaultAgentMessageMessages: AgentMessageMessages = {
	assistantRole: '助手',
	audioAttachment: '音频附件',
	documentSource: '文档来源',
	fileAttachment: '文件附件',
	imageAttachment: '图片附件',
	malformedPart: '无法显示的消息内容',
	openSource: '打开来源',
	reasoning: '提供方推理摘要',
	reasoningStreaming: '提供方正在生成推理摘要',
	step: (step) => `步骤 ${step}`,
	systemRole: '系统',
	toolApprovalReason: '审批说明',
	toolInput: '输入',
	toolOutput: '输出',
	toolState: (state, approved) => {
		switch (state) {
			case 'input-streaming':
				return '正在接收参数';
			case 'input-available':
				return '等待执行';
			case 'approval-requested':
				return '等待批准';
			case 'approval-responded':
				return approved === false ? '已拒绝' : '已批准';
			case 'output-available':
				return '已完成';
			case 'output-error':
				return '执行失败';
			case 'output-denied':
				return '已拒绝';
			default:
				return '未知状态';
		}
	},
	unknownPart: (type) => `暂不支持的消息内容：${type}`,
	unnamedAttachment: '附件',
	unnamedSource: '来源',
	unnamedTool: '工具',
	userRole: '你',
};

export function resolveAgentMessageMessages(messages?: Partial<AgentMessageMessages>): AgentMessageMessages {
	return { ...defaultAgentMessageMessages, ...messages };
}

export type AgentMessageTextRendererProps = {
	message: UIMessage;
	part: AgentMessagePart;
	streaming: boolean;
	text: string;
};

export type AgentMessageTextRenderer = ComponentType<AgentMessageTextRendererProps>;

export type AgentMessagePartRenderContext = {
	index: number;
	message: UIMessage;
	part: AgentMessagePart;
	step: number;
};

export type AgentMessagePartRenderer = (context: AgentMessagePartRenderContext) => ReactNode | undefined;

export type AgentMessageReasoningLabel = (context: {
	message: UIMessage;
	part: AgentMessagePart;
	streaming: boolean;
}) => ReactNode;

export type AgentMessageValueRecord = Record<string, unknown>;

export type AgentMessageValueProjectionLimits = {
	maxArrayItems?: number;
	maxDepth?: number;
	maxNodes?: number;
	maxObjectKeys?: number;
	maxStringLength?: number;
};

type ResolvedProjectionLimits = Required<AgentMessageValueProjectionLimits>;
type ProjectionState = {
	ancestors: WeakSet<object>;
	limits: ResolvedProjectionLimits;
	nodes: number;
};

const DEFAULT_PROJECTION_LIMITS: ResolvedProjectionLimits = {
	maxArrayItems: 32,
	maxDepth: 6,
	maxNodes: 256,
	maxObjectKeys: 32,
	maxStringLength: 1_024,
};
const TRUNCATED = '[已截断]';
const UNREADABLE = '[无法读取]';

export function isAgentMessageRecord(value: unknown): value is AgentMessageValueRecord {
	return typeof value === 'object' && value !== null;
}

export function readAgentMessageValue(value: unknown, key: string): unknown {
	if (!isAgentMessageRecord(value)) return undefined;
	try {
		return value[key];
	} catch {
		return undefined;
	}
}

export function readAgentMessageString(value: unknown, key: string): string | undefined {
	const field = readAgentMessageValue(value, key);
	return typeof field === 'string' ? field : undefined;
}

export function projectAgentMessageValue(value: unknown, limits: AgentMessageValueProjectionLimits = {}): unknown {
	const resolved = resolveProjectionLimits(limits);
	return projectValue(value, 0, { ancestors: new WeakSet(), limits: resolved, nodes: 0 });
}

export function formatAgentMessageValue(value: unknown, maxLength = 4_096): string {
	const outputLimit = boundedLimit(maxLength, 4_096);
	const projection = projectAgentMessageValue(value, {
		maxStringLength: Math.min(DEFAULT_PROJECTION_LIMITS.maxStringLength, Math.max(0, outputLimit)),
	});
	try {
		const formatted = typeof projection === 'string' ? projection : JSON.stringify(projection, null, 2);
		return truncate(formatted ?? UNREADABLE, outputLimit);
	} catch {
		return '[无法格式化]';
	}
}

export function resolveAgentMessageHref(value: unknown, kind: 'file' | 'source'): string | undefined {
	const maxLength = kind === 'file' ? 32 * 1024 * 1024 : 8 * 1024;
	if (typeof value !== 'string' || value.length > maxLength) return undefined;
	try {
		const url = new URL(value);
		if (url.protocol === 'https:' || url.protocol === 'http:') return value;
		if (kind === 'file' && (url.protocol === 'blob:' || url.protocol === 'data:')) return value;
	} catch {
		return undefined;
	}
	return undefined;
}

function projectValue(value: unknown, depth: number, state: ProjectionState): unknown {
	if (state.nodes >= state.limits.maxNodes) return TRUNCATED;
	state.nodes += 1;
	if (typeof value === 'string') return truncate(value, state.limits.maxStringLength);
	if (value === undefined) return '[undefined]';
	if (value === null || typeof value === 'number' || typeof value === 'boolean') return value;
	if (typeof value === 'bigint') return `${value.toString()}n`;
	if (typeof value === 'symbol') return `[Symbol${value.description ? `: ${truncate(value.description, 64)}` : ''}]`;
	if (typeof value === 'function') return '[Function]';
	if (typeof value !== 'object') return UNREADABLE;
	if (depth >= state.limits.maxDepth) return TRUNCATED;
	if (state.ancestors.has(value)) return '[Circular]';
	state.ancestors.add(value);
	try {
		return Array.isArray(value) ? projectArray(value, depth, state) : projectObject(value, depth, state);
	} catch {
		return UNREADABLE;
	} finally {
		state.ancestors.delete(value);
	}
}

function projectArray(value: unknown[], depth: number, state: ProjectionState): unknown[] {
	const lengthDescriptor = safeOwnDescriptor(value, 'length');
	if (!lengthDescriptor || !('value' in lengthDescriptor) || typeof lengthDescriptor.value !== 'number') {
		return [UNREADABLE];
	}
	const length = Math.max(0, Math.floor(lengthDescriptor.value));
	const count = Math.min(length, state.limits.maxArrayItems);
	const output: unknown[] = [];
	for (let index = 0; index < count && state.nodes < state.limits.maxNodes; index += 1) {
		const descriptor = safeOwnDescriptor(value, String(index));
		output.push(projectDescriptor(descriptor, depth + 1, state));
	}
	if (length > count) output.push(`${TRUNCATED} ${length - count} 项`);
	return output;
}

function projectObject(value: object, depth: number, state: ProjectionState): AgentMessageValueRecord {
	const output = Object.create(null) as AgentMessageValueRecord;
	let inspected = 0;
	let projected = 0;
	let truncated = false;
	try {
		for (const key in value) {
			inspected += 1;
			if (inspected > state.limits.maxObjectKeys || state.nodes >= state.limits.maxNodes) {
				truncated = true;
				break;
			}
			let own = false;
			try {
				own = Object.hasOwn(value, key);
			} catch {
				defineProjection(output, truncate(key, 256), UNREADABLE);
				projected += 1;
				continue;
			}
			if (!own) continue;
			const safeKey = truncate(key, 256);
			defineProjection(output, safeKey, projectDescriptor(safeOwnDescriptor(value, key), depth + 1, state));
			projected += 1;
		}
	} catch {
		defineProjection(output, '[读取错误]', UNREADABLE);
	}
	if (truncated || projected >= state.limits.maxObjectKeys) defineProjection(output, '[更多字段]', TRUNCATED);
	return output;
}

function projectDescriptor(descriptor: PropertyDescriptor | undefined, depth: number, state: ProjectionState): unknown {
	if (!descriptor) return '[缺失]';
	if (!('value' in descriptor)) return '[Accessor]';
	return projectValue(descriptor.value, depth, state);
}

function safeOwnDescriptor(value: object, key: PropertyKey): PropertyDescriptor | undefined {
	try {
		return Object.getOwnPropertyDescriptor(value, key);
	} catch {
		return undefined;
	}
}

function defineProjection(target: AgentMessageValueRecord, key: string, value: unknown) {
	Object.defineProperty(target, key, { configurable: true, enumerable: true, value, writable: true });
}

function resolveProjectionLimits(limits: AgentMessageValueProjectionLimits): ResolvedProjectionLimits {
	return {
		maxArrayItems: boundedLimit(limits.maxArrayItems, DEFAULT_PROJECTION_LIMITS.maxArrayItems),
		maxDepth: boundedLimit(limits.maxDepth, DEFAULT_PROJECTION_LIMITS.maxDepth),
		maxNodes: boundedLimit(limits.maxNodes, DEFAULT_PROJECTION_LIMITS.maxNodes),
		maxObjectKeys: boundedLimit(limits.maxObjectKeys, DEFAULT_PROJECTION_LIMITS.maxObjectKeys),
		maxStringLength: boundedLimit(limits.maxStringLength, DEFAULT_PROJECTION_LIMITS.maxStringLength),
	};
}

function boundedLimit(value: number | undefined, fallback: number): number {
	return value === undefined || !Number.isFinite(value) ? fallback : Math.max(0, Math.floor(value));
}

function truncate(value: string, maxLength: number): string {
	const limit = boundedLimit(maxLength, 4_096);
	return value.length <= limit ? value : `${value.slice(0, Math.max(0, limit - 1))}…`;
}

'use client';

import type { ComponentPropsWithRef } from 'react';
import { Streamdown } from 'streamdown';
import { cn } from '@/lib/utils';
import type { AgentMessageTextRendererProps } from './agent-message-types';

export type AgentMarkdownProps = Omit<ComponentPropsWithRef<'div'>, 'children'> & {
	children: string;
	streaming?: boolean;
};

export function AgentMarkdown({ children, className, streaming = false, ...props }: AgentMarkdownProps) {
	return (
		<div
			data-slot='agent-markdown'
			data-streaming={streaming ? 'true' : 'false'}
			className={cn(
				'[&_a]:text-primary [&_code]:bg-muted [&_pre]:bg-muted max-w-full min-w-0 leading-6 [&_a]:underline [&_a]:underline-offset-4 [&_blockquote]:border-l-2 [&_blockquote]:pl-3 [&_code]:rounded-sm [&_code]:px-1 [&_h1]:text-lg [&_h1]:font-semibold [&_h2]:text-base [&_h2]:font-semibold [&_ol]:list-decimal [&_ol]:pl-5 [&_p+p]:mt-3 [&_pre]:max-w-full [&_pre]:overflow-x-auto [&_pre]:rounded-md [&_pre]:p-3 [&_table]:block [&_table]:max-w-full [&_table]:overflow-x-auto [&_ul]:list-disc [&_ul]:pl-5',
				className,
			)}
			{...props}
		>
			<Streamdown>{children}</Streamdown>
		</div>
	);
}

export function AgentMessageDefaultTextRenderer({ text, streaming }: AgentMessageTextRendererProps) {
	return <AgentMarkdown streaming={streaming}>{text}</AgentMarkdown>;
}

'use client';

import { ExternalLink, FileText, Image as ImageIcon, Music2, Wrench } from 'lucide-react';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { AgentMessageDefaultTextRenderer } from './agent-markdown';
import type {
	AgentMessageMessages,
	AgentMessagePart,
	AgentMessageReasoningLabel,
	AgentMessageTextRenderer,
} from './agent-message-types';
import {
	formatAgentMessageValue,
	isAgentMessageRecord,
	readAgentMessageString,
	readAgentMessageValue,
	resolveAgentMessageHref,
} from './agent-message-value';

export type AgentMessagePartPresenterProps = Omit<ComponentPropsWithRef<'div'>, 'part'> & {
	index: number;
	message: import('ai').UIMessage;
	messages: AgentMessageMessages;
	part: unknown;
	reasoningLabel?: AgentMessageReasoningLabel;
	role: import('ai').UIMessage['role'];
	step: number;
	textRenderer?: AgentMessageTextRenderer;
};

export function AgentMessagePartPresenter({
	className,
	index,
	message,
	messages,
	part,
	reasoningLabel,
	role,
	step,
	textRenderer: TextRenderer = AgentMessageDefaultTextRenderer,
	...props
}: AgentMessagePartPresenterProps) {
	const type = readAgentMessageString(part, 'type');
	let content: ReactNode;

	if (!type) {
		content = <AgentMessagePartFallback label={messages.malformedPart} />;
	} else if (type === 'text') {
		const text = readAgentMessageString(part, 'text');
		content =
			text === undefined ? (
				<AgentMessagePartFallback label={messages.malformedPart} />
			) : (
				<TextRenderer
					message={message}
					part={part as AgentMessagePart}
					streaming={readAgentMessageString(part, 'state') === 'streaming'}
					text={text}
				/>
			);
	} else if (type === 'reasoning') {
		content = renderReasoning({ message, messages, part, reasoningLabel, TextRenderer });
	} else if (type === 'file' || type === 'reasoning-file') {
		content = <AgentMessageFile messages={messages} part={part} />;
	} else if (type === 'source-url' || type === 'source-document') {
		content = <AgentMessageSource messages={messages} part={part} type={type} />;
	} else if (type === 'step-start') {
		content = <AgentMessageStep label={messages.step(step)} />;
	} else if (type === 'dynamic-tool' || type.startsWith('tool-')) {
		content = <AgentMessageTool messages={messages} part={part} type={type} />;
	} else {
		content = <AgentMessagePartFallback label={messages.unknownPart(type)} />;
	}

	return (
		<div
			data-slot='agent-message-part'
			data-part-index={index}
			data-part-type={type ?? 'malformed'}
			data-role={role}
			className={cn(
				'max-w-full min-w-0',
				role === 'user' &&
					type === 'text' &&
					'bg-primary text-primary-foreground w-fit max-w-[min(42rem,90%)] rounded-md px-3 py-2',
				role === 'system' && 'border-info bg-info/10 w-full border-l-2 px-3 py-2',
				className,
			)}
			{...props}
		>
			{content}
		</div>
	);
}

function renderReasoning({
	message,
	messages,
	part,
	reasoningLabel,
	TextRenderer,
}: {
	message: import('ai').UIMessage;
	messages: AgentMessageMessages;
	part: unknown;
	reasoningLabel?: AgentMessageReasoningLabel;
	TextRenderer: AgentMessageTextRenderer;
}) {
	const text = readAgentMessageString(part, 'text');
	if (text === undefined) return <AgentMessagePartFallback label={messages.malformedPart} />;
	const streaming = readAgentMessageString(part, 'state') === 'streaming';
	const label =
		reasoningLabel?.({ message, part: part as AgentMessagePart, streaming }) ??
		(streaming ? messages.reasoningStreaming : messages.reasoning);
	return (
		<details
			data-slot='agent-message-reasoning'
			open={streaming || undefined}
			className='border-border max-w-full border-l-2 pl-3'
		>
			<summary className='text-muted-foreground cursor-pointer text-xs font-medium'>{label}</summary>
			<div className='text-muted-foreground mt-2'>
				<TextRenderer message={message} part={part as AgentMessagePart} streaming={streaming} text={text} />
			</div>
		</details>
	);
}

function AgentMessageFile({ messages, part }: { messages: AgentMessageMessages; part: unknown }) {
	const mediaType = readAgentMessageString(part, 'mediaType') ?? '';
	const filename = readAgentMessageString(part, 'filename') ?? messages.unnamedAttachment;
	const url = resolveAgentMessageHref(readAgentMessageValue(part, 'url'), 'file');
	if (!url) return <AgentMessagePartFallback label={messages.malformedPart} />;

	if (mediaType === 'image' || mediaType.startsWith('image/')) {
		return (
			<figure data-slot='agent-message-attachment' data-media='image' className='w-fit max-w-full'>
				<img
					alt={`${messages.imageAttachment}：${filename}`}
					className='border-border max-h-80 w-auto max-w-full rounded-md border object-contain'
					height={240}
					loading='lazy'
					src={url}
					width={320}
				/>
				<figcaption className='text-muted-foreground mt-1 flex items-center gap-1 text-xs'>
					<ImageIcon aria-hidden='true' className='size-3.5' /> {filename}
				</figcaption>
			</figure>
		);
	}
	if (mediaType === 'audio' || mediaType.startsWith('audio/')) {
		return (
			<figure data-slot='agent-message-attachment' data-media='audio' className='max-w-full'>
				<figcaption className='text-muted-foreground mb-1 flex items-center gap-1 text-xs'>
					<Music2 aria-hidden='true' className='size-3.5' /> {filename}
				</figcaption>
				{/* biome-ignore lint/a11y/useMediaCaption: Provider attachments do not include a transcript track. */}
				<audio
					aria-label={`${messages.audioAttachment}：${filename}`}
					className='h-10 w-full max-w-md'
					controls
					preload='metadata'
					src={url}
				/>
			</figure>
		);
	}
	return (
		<a
			data-slot='agent-message-attachment'
			data-media='file'
			className='border-border hover:bg-muted flex min-h-9 w-fit max-w-full items-center gap-2 rounded-md border px-2.5 py-1.5 text-sm'
			download={filename}
			href={url}
		>
			<FileText aria-hidden='true' className='size-4 shrink-0' />
			<span className='truncate'>{filename}</span>
		</a>
	);
}

function AgentMessageSource({
	messages,
	part,
	type,
}: {
	messages: AgentMessageMessages;
	part: unknown;
	type: 'source-url' | 'source-document';
}) {
	const title =
		readAgentMessageString(part, 'title') ?? readAgentMessageString(part, 'filename') ?? messages.unnamedSource;
	if (type === 'source-document') {
		return (
			<span
				data-slot='agent-message-source'
				className='text-muted-foreground inline-flex min-h-7 max-w-full items-center gap-1.5 text-xs'
			>
				<FileText aria-hidden='true' className='size-3.5 shrink-0' />
				<span className='truncate'>
					{messages.documentSource}：{title}
				</span>
			</span>
		);
	}
	const url = resolveAgentMessageHref(readAgentMessageValue(part, 'url'), 'source');
	if (!url) return <AgentMessagePartFallback label={messages.malformedPart} />;
	return (
		<a
			data-slot='agent-message-source'
			className='text-primary inline-flex min-h-7 max-w-full items-center gap-1.5 text-xs underline underline-offset-4'
			href={url}
			rel='noreferrer'
			target='_blank'
			title={messages.openSource}
		>
			<ExternalLink aria-hidden='true' className='size-3.5 shrink-0' />
			<span className='truncate'>{title}</span>
		</a>
	);
}

function AgentMessageStep({ label }: { label: string }) {
	return (
		<div data-slot='agent-message-step' className='text-muted-foreground flex min-h-6 items-center gap-2 text-xs'>
			<span className='border-border h-px flex-1 border-t' />
			<span>{label}</span>
			<span className='border-border h-px flex-1 border-t' />
		</div>
	);
}

function AgentMessageTool({ messages, part, type }: { messages: AgentMessageMessages; part: unknown; type: string }) {
	const state = readAgentMessageString(part, 'state') ?? 'unknown';
	const toolName = type === 'dynamic-tool' ? readAgentMessageString(part, 'toolName') : type.slice('tool-'.length);
	const title = readAgentMessageString(part, 'title') ?? toolName ?? messages.unnamedTool;
	const approval = readAgentMessageValue(part, 'approval');
	const approved =
		isAgentMessageRecord(approval) && typeof readAgentMessageValue(approval, 'approved') === 'boolean'
			? (readAgentMessageValue(approval, 'approved') as boolean)
			: undefined;
	const input = readAgentMessageValue(part, 'input');
	const output = readAgentMessageValue(part, 'output');
	const error = readAgentMessageString(part, 'errorText');
	const reason = isAgentMessageRecord(approval) ? readAgentMessageString(approval, 'reason') : undefined;
	return (
		<details
			data-slot='agent-message-tool'
			data-state={state}
			open={state === 'approval-requested' || state === 'output-error' || undefined}
			className='border-border w-full max-w-2xl rounded-md border'
		>
			<summary className='hover:bg-muted flex min-h-10 cursor-pointer list-none items-center gap-2 px-3 py-2'>
				<Wrench aria-hidden='true' className='text-muted-foreground size-4 shrink-0' />
				<span className='min-w-0 flex-1 truncate text-sm font-medium'>{title}</span>
				<span className='badge badge-ghost badge-sm shrink-0'>{messages.toolState(state, approved)}</span>
			</summary>
			<div className='border-border space-y-3 border-t px-3 py-2 text-xs'>
				{input !== undefined ? <AgentMessageToolValue label={messages.toolInput} value={input} /> : null}
				{output !== undefined ? <AgentMessageToolValue label={messages.toolOutput} value={output} /> : null}
				{error ? <AgentMessageToolValue error label={messages.toolOutput} value={error} /> : null}
				{reason ? <AgentMessageToolValue label={messages.toolApprovalReason} value={reason} /> : null}
			</div>
		</details>
	);
}

function AgentMessageToolValue({ error = false, label, value }: { error?: boolean; label: string; value: unknown }) {
	return (
		<div>
			<div className='text-muted-foreground mb-1 font-medium'>{label}</div>
			<pre
				className={cn(
					'bg-muted max-h-64 overflow-auto rounded-sm p-2 whitespace-pre-wrap',
					error && 'bg-error/10 text-error',
				)}
			>
				{formatAgentMessageValue(value)}
			</pre>
		</div>
	);
}

function AgentMessagePartFallback({ label }: { label: string }) {
	return (
		<div
			data-slot='agent-message-part-fallback'
			role='status'
			className='text-muted-foreground border-border rounded-sm border border-dashed px-2.5 py-2 text-xs'
		>
			{label}
		</div>
	);
}

'use client';

import type { UIMessage } from 'ai';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { Message, MessageAvatar, MessageContent, MessageFooter, MessageHeader } from '../message';
import { AgentMessagePartPresenter } from './agent-message-parts';
import type {
	AgentMessageMessages,
	AgentMessagePartRenderer,
	AgentMessageReasoningLabel,
	AgentMessageTextRenderer,
} from './agent-message-types';
import { resolveAgentMessageMessages } from './agent-message-types';
import { readAgentMessageString, readAgentMessageValue } from './agent-message-value';

export type AgentMessageProps = Omit<ComponentPropsWithRef<typeof Message>, 'align' | 'children'> & {
	actions?: ReactNode;
	avatar?: ReactNode;
	header?: ReactNode;
	message: UIMessage;
	messages?: Partial<AgentMessageMessages>;
	meta?: ReactNode;
	reasoningLabel?: AgentMessageReasoningLabel;
	renderPart?: AgentMessagePartRenderer;
	renderTool?: AgentMessagePartRenderer;
	showHeader?: boolean;
	textRenderer?: AgentMessageTextRenderer;
	usage?: ReactNode;
};

export function AgentMessage({
	actions,
	avatar,
	className,
	header,
	message,
	messages,
	meta,
	reasoningLabel,
	renderPart,
	renderTool,
	showHeader = true,
	textRenderer,
	usage,
	...props
}: AgentMessageProps) {
	const copy = resolveAgentMessageMessages(messages);
	const role = resolveRole(message.role);
	const rawParts: unknown[] = Array.isArray(message.parts) ? message.parts : [message.parts];
	let step = 0;
	return (
		<Message
			align={role === 'user' ? 'end' : 'start'}
			data-role={role}
			data-slot='agent-message'
			className={cn('py-1', className)}
			{...props}
		>
			{avatar !== undefined ? <MessageAvatar>{avatar}</MessageAvatar> : null}
			<MessageContent>
				{showHeader ? <MessageHeader>{header ?? roleLabel(role, copy)}</MessageHeader> : null}
				{rawParts.map((part, index) => {
					if (readAgentMessageString(part, 'type') === 'step-start') step += 1;
					const context = { index, message, part: part as UIMessage['parts'][number], step };
					const key = messagePartKey(message.id, index, part);
					const custom = renderPart?.(context);
					if (custom !== undefined) return <AgentMessageCustomPart key={key}>{custom}</AgentMessageCustomPart>;
					const type = readAgentMessageString(part, 'type');
					if (type === 'dynamic-tool' || type?.startsWith('tool-')) {
						const customTool = renderTool?.(context);
						if (customTool !== undefined) {
							return <AgentMessageCustomPart key={key}>{customTool}</AgentMessageCustomPart>;
						}
					}
					return (
						<AgentMessagePartPresenter
							key={key}
							index={index}
							message={message}
							messages={copy}
							part={part}
							reasoningLabel={reasoningLabel}
							role={role}
							step={step}
							textRenderer={textRenderer}
						/>
					);
				})}
				{actions !== undefined || usage !== undefined || meta !== undefined ? (
					<MessageFooter>
						{meta !== undefined ? <AgentMessageMeta>{meta}</AgentMessageMeta> : null}
						{usage !== undefined ? <AgentMessageUsage>{usage}</AgentMessageUsage> : null}
						{actions !== undefined ? <AgentMessageActions>{actions}</AgentMessageActions> : null}
					</MessageFooter>
				) : null}
			</MessageContent>
		</Message>
	);
}

export type AgentMessageActionsProps = ComponentPropsWithRef<'div'>;

export function AgentMessageActions({ className, ...props }: AgentMessageActionsProps) {
	return (
		<div data-slot='agent-message-actions' className={cn('flex min-h-8 items-center gap-1', className)} {...props} />
	);
}

export type AgentMessageUsageProps = ComponentPropsWithRef<'span'>;

export function AgentMessageUsage({ className, ...props }: AgentMessageUsageProps) {
	return <span data-slot='agent-message-usage' className={cn('whitespace-nowrap', className)} {...props} />;
}

export type AgentMessageMetaProps = ComponentPropsWithRef<'span'>;

export function AgentMessageMeta({ className, ...props }: AgentMessageMetaProps) {
	return <span data-slot='agent-message-meta' className={cn('min-w-0 truncate', className)} {...props} />;
}

function AgentMessageCustomPart({ children }: { children: ReactNode }) {
	return (
		<div data-slot='agent-message-part' data-part-type='custom-renderer'>
			{children}
		</div>
	);
}

function messagePartKey(messageId: string, index: number, part: unknown): string {
	const approvalId = readAgentMessageString(readAgentMessageValue(part, 'approval'), 'id');
	const toolCallId = readAgentMessageString(part, 'toolCallId');
	return `${messageId}-${index}-${approvalId ?? toolCallId ?? ''}`;
}

function resolveRole(role: unknown): UIMessage['role'] {
	return role === 'user' || role === 'system' || role === 'assistant' ? role : 'assistant';
}

function roleLabel(role: UIMessage['role'], messages: AgentMessageMessages) {
	if (role === 'user') return messages.userRole;
	if (role === 'system') return messages.systemRole;
	return messages.assistantRole;
}

